import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:20px;line-height:1.3}.box h2{font-size:23px;margin-bottom:4px}.tbl{font-size:17.5px}.note,.warn{font-size:17px}.tbl th,.tbl td{padding:2px 6px}.iq ol{font-size:19px;line-height:1.26}.pill{font-size:16px}.grid{gap:10px}.handle{bottom:-12px}.box{padding:9px 12px}.tagline{font-size:19px;margin-bottom:9px}.code{font-family:Consolas,'DejaVu Sans Mono',monospace;background:#f1f5f9;border:1px dashed #94a3b8;border-radius:6px;padding:5px 7px;margin:4px 0;line-height:1.3;font-size:16px}</style>
<div class="title">🛡️ HxGN EAM RCM: Risk &amp; Reliability <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Reliability Centered Maintenance: Risk Matrix → Risk Assessment / Analysis / FMECA → Mitigation with PMs. (Infor EAM RCM brief, 11.7 docs)</div>
<div class="grid">
<div class="box c1"><h2>1. Setup: project + matrix</h2><ul><li>RCM Project = System Codes entity <b>STPR</b> (max 8 chars, system code *)</li><li><b>Default</b> project's matrix is used unless the <b>Organization</b> picks an RCM Project</li><li>One <b>Risk Matrix</b> per RCM Project</li></ul></div>
<div class="box c2"><h2>2. Risk Matrix Setup types</h2><table class="tbl"><tr><th>Type</th><th>Example</th></tr><tr><td>Consequence Category</td><td>Safety, Environment, Profitability</td></tr><tr><td>Probability</td><td>&lt;1 yr, 1–5 yrs, &gt;20 yrs</td></tr><tr><td>Risk Level</td><td>Desirable … Catastrophic</td></tr></table><div class="note">Consequences + Severity on the Consequences tab; cost per Organization on Consequence Cost tab.</div></div>
<div class="box c3"><h2>3. The RPN formula</h2><div class="code">RPN = Probability Rating<br>    × Consequence Severity</div><ul><li>Most desirable = <b>1</b>, higher = worse</li><li>Header shows the <b>highest</b> RPN from the RCM tab</li><li>Risk Level = matrix level matching the RPN via Rating/Threshold</li></ul></div>
<div class="box c4"><h2>4. Pick the RCM Level</h2><table class="tbl"><tr><th>Level</th><th>Defines</th><th>Where</th></tr><tr><td>Risk Assessment</td><td>Functions → Functional Failures → Consequences</td><td>High in hierarchy (lines, locations)</td></tr><tr><td>Risk Analysis</td><td>+ Failure Modes</td><td>Lower-level equipment</td></tr><tr><td>FMECA</td><td>Failure Modes instead of Functional Failures</td><td>Any</td></tr></table></div>
<div class="box c5"><h2>5. Build the RCM tab tree</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Functions</span><span class="arr">→</span><span class="pill">Functional Failures</span><span class="arr">→</span><span class="pill">Consequences</span><span class="arr">→</span><span class="pill">Failure Modes</span><span class="arr">→</span><span class="pill">FF for Failure Modes</span></div><ul><li>Failure Mode holds WO defaults: closing codes, Standard WO, downtime, TACA / HUFA / WOMS / HUOV / MOFD</li><li>Picking it on a WO defaults these</li></ul></div>
<div class="box c6"><h2>6. Black Swan ⚫🦢</h2><ul><li>Low probability, very high cost</li><li>Tick it only on the <b>lowest</b> probability and <b>worst</b> consequence</li><li>Header flags Black Swan + <b>Black Swan Cost</b> when both match</li></ul><div class="warn">Usually doesn't drive the RPN, so it's easy to overlook. That's why it's flagged.</div></div>
<div class="box c7"><h2>7. Failure Mitigation tab</h2><ul><li>Only for <b>Risk Analysis / FMECA</b></li><li>Mitigated Probability → new RPN preview</li><li>Measures: PM Schedule, Maintenance Pattern, PM Plan, Project, Case, Aspect</li><li>One-time + Recurring Mitigation Cost</li><li><b>Mitigation Applied</b> = active; lowest active rating wins</li></ul></div>
<div class="box c8"><h2>8. Activate Mitigation</h2><ul><li>Adds equipment to the PM Schedule + syncs intervals</li><li>Adds to Maintenance Pattern, activates 1st sequence</li><li>Adds to PM Plan</li></ul><div class="code">PM State: Not attached | Multiple attached<br>| Not active | Different frequency<br>| Different meter UOM | Mitigated</div></div>
<div class="box c1"><h2>9. RCM Templates</h2><ul><li>Status <b>RTST</b>: Unfinished → Request Approval → Approved → Superseded</li><li>Revision control; RCM data editable only when Unfinished</li><li>Equipment Classes tab: */* = generic</li><li>Import: Probabilities / Consequences / Mitigation (always imported <b>not</b> applied)</li></ul></div>
<div class="box c2"><h2>10. Reports</h2><table class="tbl"><tr><th>Report</th><th>Shows</th></tr><tr><td>Risk Matrix</td><td>Matrix + counts per cell</td></tr><tr><td>RCM Risk Levels</td><td>Equipment by Risk Level</td></tr><tr><td>Equipment at Risk</td><td>Risky, no active PM / pattern</td></tr><tr><td>Potential Yearly Savings</td><td>Low risk but PM active</td></tr></table></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">11a. RCM loop</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Assess line</span><span class="arr">→</span><span class="pill">Analyse high-risk child</span><span class="arr">→</span><span class="pill">Mitigate top RPN</span><span class="arr">→</span><span class="pill">Activate PM</span><span class="arr">→</span><span class="pill">Report</span></div></div>
<div class="box iq"><h2>11b. Consultant tips</h2><ol><li>Matrix edits don't trickle down: re-check RCM tabs</li><li>Analysis → Assessment needs Failure Modes deleted</li><li>Start mitigation at the highest RPN</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">11c. Key points</h2><ul><li>3 RCM Levels</li><li>RPN = P × S</li><li>4 RCM reports</li></ul></div>
</div></div>'''
build("/workspace/instagram-assets/posts/2026-11-01-linkedin-eam-rcm",B,1620,"Rahul Kumar")
